package com.example.lending;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.Map;
import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class MemberSuspensionIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void new_member_is_not_suspended_and_registration_response_is_unchanged() throws Exception {
        String body = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"권나은\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.suspended").doesNotExist())
                .andReturn().getResponse().getContentAsString();
        String memberId = objectMapper.readTree(body).get("memberId").asText();

        mockMvc.perform(get("/members/{memberId}", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.suspended").value(false));
    }

    @Test
    void suspended_member_cannot_borrow_until_unsuspended() throws Exception {
        String memberId = registerMember("노지훈");
        String bookId = registerBook("Suspension Borrow Check");

        mockMvc.perform(post("/members/{memberId}/suspend", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.suspended").value(true));
        mockMvc.perform(get("/members/{memberId}", memberId))
                .andExpect(jsonPath("$.suspended").value(true));

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanBody(bookId, memberId)))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("MEMBER_SUSPENDED"));
        mockMvc.perform(get("/books").param("title", "Suspension Borrow Check"))
                .andExpect(jsonPath("$[0].status").value("AVAILABLE"));

        mockMvc.perform(post("/members/{memberId}/unsuspend", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.suspended").value(false));
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanBody(bookId, memberId)))
                .andExpect(status().isCreated());
    }

    @Test
    void suspending_or_unsuspending_an_unknown_member_returns_404() throws Exception {
        mockMvc.perform(post("/members/{memberId}/suspend", UUID.randomUUID().toString()))
                .andExpect(status().isNotFound());
        mockMvc.perform(post("/members/{memberId}/unsuspend", UUID.randomUUID().toString()))
                .andExpect(status().isNotFound());
    }

    private String loanBody(String bookId, String memberId) throws Exception {
        return objectMapper.writeValueAsString(Map.of("bookId", bookId, "memberId", memberId));
    }

    private String registerMember(String name) throws Exception {
        String body = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"" + name + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(body).get("memberId").asText();
    }

    private String registerBook(String title) throws Exception {
        String body = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(body).get("id").asText();
    }
}
